DATA = "diff --git a/apps/daemon/src/byok/credential-service.ts b/apps/daemon/src/byok/credential-service.ts\nindex 4146c35..88fbeff 100644\n--- a/apps/daemon/src/byok/credential-service.ts\n+++ b/apps/daemon/src/byok/credential-service.ts\n@@ -1,6 +1,6 @@\n import { spawn } from 'node:child_process';\n import { randomUUID } from 'node:crypto';\n-import { access, mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';\n+import { access, mkdir, open, readFile, rename, unlink, writeFile } from 'node:fs/promises';\n import path from 'node:path';\n import type {\n   ByokChatProviderConfig,\n@@ -16,6 +16,9 @@ const PROFILE_ID_PATTERN = /^byok-[a-z0-9][a-z0-9._-]{2,95}$/u;\n const KEYCHAIN_SERVICE = 'dev.opendesign.byok';\n const MAX_SECRET_OUTPUT_BYTES = 64 * 1024;\n const INTERACTIVE_SECRET_TIMEOUT_MS = 10_000;\n+const WINDOWS_DPAPI_TIMEOUT_MS = 10_000;\n+const WINDOWS_CIPHERTEXT_LIMIT = 128 * 1024;\n+const WINDOWS_SECRET_LIMIT = 32 * 1024;\n \n type StoredProfile = Omit<ByokCredentialProfile, 'configured' | 'keyTail'>;\n type StoredDocument = {\n@@ -346,9 +349,7 @@ export function createPlatformByokSecretBackend(\n   if (platform === 'darwin') return new MacOsKeychainBackend();\n   if (platform === 'linux') return new LinuxSecretServiceBackend();\n   if (platform === 'win32' && dataDir) {\n-    return new RetiredWindowsSecretCleanupBackend(\n-      path.join(dataDir, 'byok', 'secrets'),\n-    );\n+    return new WindowsDpapiSecretBackend(path.join(dataDir, 'byok', 'secrets'));\n   }\n   return new UnavailableSecretBackend(platform);\n }\n@@ -452,15 +453,107 @@ class UnavailableSecretBackend implements ByokSecretBackend {\n   async delete(_profileId: string) { return false; }\n }\n \n-class RetiredWindowsSecretCleanupBackend extends UnavailableSecretBackend {\n-  constructor(private readonly secretsDir: string) {\n-    super('win32');\n+/**\n+ * CurrentUser DPAPI binds ciphertext to the logged-in Windows identity. The\n+ * fixed script receives base64 JSON on stdin; neither secret nor profile id\n+ * is embedded in executable arguments, shell syntax, or PowerShell logs.\n+ */\n+const WINDOWS_DPAPI_SCRIPT = [\n+  \"$ErrorActionPreference = 'Stop'\",\n+  'try {',\n+  '  $inputData = [Console]::In.ReadToEnd() | ConvertFrom-Json',\n+  '  $entropy = [Text.Encoding]::UTF8.GetBytes($inputData.entropy)',\n+  '  if ($inputData.action -eq \"protect\") {',\n+  '    $bytes = [Convert]::FromBase64String($inputData.value)',\n+  '    $result = [Security.Cryptography.ProtectedData]::Protect($bytes, $entropy, [Security.Cryptography.DataProtectionScope]::CurrentUser)',\n+  '  } elseif ($inputData.action -eq \"unprotect\") {',\n+  '    $bytes = [Convert]::FromBase64String($inputData.value)',\n+  '    $result = [Security.Cryptography.ProtectedData]::Unprotect($bytes, $entropy, [Security.Cryptography.DataProtectionScope]::CurrentUser)',\n+  '  } else { throw \"Invalid action\" }',\n+  '  [Console]::Out.Write([Convert]::ToBase64String($result))',\n+  '} catch { exit 1 }',\n+].join('\\n');\n+\n+class WindowsDpapiSecretBackend implements ByokSecretBackend {\n+  readonly kind = 'windows-dpapi-current-user';\n+\n+  constructor(private readonly secretsDir: string) {}\n+\n+  async available(): Promise<boolean> {\n+    return process.platform === 'win32' && await commandAvailable('powershell.exe');\n+  }\n+\n+  private secretPath(profileId: string): string {\n+    assertProfileId(profileId);\n+    return path.join(this.secretsDir, `${profileId}.bin`);\n   }\n \n-  override async delete(profileId: string) {\n-    assertProfileId(profileId);\n+  async set(profileId: string, secret: string): Promise<void> {\n+    const target = this.secretPath(profileId);\n+    if (!await this.available()) {\n+      throw new Error('Secure credential storage is unavailable on this system.');\n+    }\n+    const bytes = Buffer.from(secret, 'utf8');\n+    if (!bytes.length || bytes.length > WINDOWS_SECRET_LIMIT) {\n+      throw new Error('BYOK credential has an invalid size.');\n+    }\n+    const encrypted = await runWindowsDpapi('protect', profileId, bytes.toString('base64'));\n+    if (!/^[A-Za-z0-9+/]+={0,2}$/u.test(encrypted) || encrypted.length > WINDOWS_CIPHERTEXT_LIMIT) {\n+      throw new Error('Secure credential backend command failed.');\n+    }\n+    await mkdir(this.secretsDir, { recursive: true, mode: 0o700 });\n+    const temporary = `${target}.${randomUUID()}.tmp`;\n+    try {\n+      await writeFile(temporary, encrypted, { encoding: 'ascii', mode: 0o600, flag: 'wx' });\n+      await rename(temporary, target);\n+    } finally {\n+      await unlink(temporary).catch((error: NodeJS.ErrnoException) => {\n+        if (error.code !== 'ENOENT') throw error;\n+      });\n+    }\n+  }\n+\n+  async get(profileId: string): Promise<string | null> {\n+    const target = this.secretPath(profileId);\n+    let encrypted: string;\n+    try {\n+      // Read a single opened resource, with an explicit cap even if it grows.\n+      const file = await open(target, 'r');\n+      try {\n+        const buffer = Buffer.alloc(WINDOWS_CIPHERTEXT_LIMIT + 1);\n+        const { bytesRead } = await file.read(buffer, 0, buffer.length, 0);\n+        if (bytesRead > WINDOWS_CIPHERTEXT_LIMIT) {\n+          throw new Error('Secure credential backend command failed.');\n+        }\n+        "
